import type { SupportedLocale } from "@/i18n/config";
import type { LocaleFollowup } from "@/i18n/dictionaries/locale-quality-followup";

type Entry = [formula: string, example: string, question: string, answer: string];
type Copy = { vat: Entry; irpf: Entry; severance: Entry };
type Instructions = { vat: string; irpf: string; severance: string };

// Localized additions describe the calculator's actual arithmetic separately from Spanish legal scope.
const copy: Record<SupportedLocale, Copy> = {
  ko: {
    vat: ["세율을 r%로 입력하면 공급가액 기준 IVA=r×공급가액/100, 총액=공급가액+IVA입니다. 세금 포함액이면 공급가액=총액/(1+r/100)으로 역산합니다. 2026-10-28 확인한 스페인 세무청은 일반세율 21%, 특정 거래의 10%·4%·0%를 안내하지만 이 도구는 품목을 분류하지 않습니다.", "공급가액 €1,000과 입력 세율 21%이면 IVA €210, 합계 €1,210입니다. 21%는 일반세율이며 적용 세율은 상품·서비스와 거래 조건에 따라 달라질 수 있습니다.", "21%가 모든 거래에 적용되나요?", "아니요. 스페인 세무청은 특정 거래에 10%, 4% 또는 0%가 적용될 수 있다고 안내합니다. 이 도구는 입력한 비율만 계산하며 면세·영세율 자격이나 거래 장소를 판단하지 않습니다."],
    irpf: ["엔진은 연간 과세소득에 사용자가 입력한 단일 비율을 곱합니다: 추정세액=소득×입력 비율/100, 평균세율=세액/소득×100. IRPF 법률은 국가 및 자치주 구간과 개인별 요소를 포함하지만, 이 도구는 해당 누진세 체계를 계산하지 않습니다.", "연간 과세소득 €30,000에 15%를 입력하면 €4,500, 계산상 평균 15%입니다. 이는 입력 비율에 따른 산술 예시이지 스페인 신고세액이나 법정 세율이 아닙니다.", "이 결과가 스페인 IRPF 신고액인가요?", "아닙니다. Ley 35/2006 제63조와 제74조의 국가·자치주 과세 구조는 입력 소득과 단일 비율만 받는 이 도구에 구현되어 있지 않습니다. 공제, 개인·가족 최소액, 거주 자치주와 소득 유형도 고려하지 않습니다."],
    severance: ["도구의 산식은 일급 기준=월급×12/365, 예시 보상액=일급×입력 일수/근속연도×입력 근속연수입니다. 스페인 근로자법은 해고 사유별 일수와 상한을 달리 정하며, 이 도구는 사유·계약일·법정 상한을 판별하지 않습니다.", "월급 €2,500, 근속 5년, 입력값 20일/년이면 일급 환산 €82.1918을 사용해 €8,219.18입니다. 입력 가정에 따른 금액으로 법정 지급액 판정은 아닙니다.", "20일 또는 33일을 선택하면 법정액인가요?", "그렇게 단정할 수 없습니다. 근로자법 제53조와 제56조는 사유별 요율·월수 상한을 두고, 2012년 2월 12일 이전 계약에는 경과 규정이 있을 수 있습니다. 이 계산기는 이를 적용하지 않습니다."],
  },
  en: {
    vat: ["For entered rate r%, VAT on a net amount is amount×r/100 and gross is net+VAT. For an inclusive amount, net=total/(1+r/100). Checked 2026-10-28, Spain's Tax Agency lists 21% as the general rate and 10%, 4% or 0% for specified operations; this tool does not classify supplies.", "A €1,000 net amount at the entered 21% gives €210 VAT and €1,210 gross. 21% is the general rate; the applicable rate can depend on the item and transaction.", "Does 21% apply to every transaction?", "No. The Tax Agency lists reduced rates of 10% and 4%, and 0% for certain operations. This calculator applies your chosen rate only; it does not decide exemptions, zero-rating or place of supply."],
    irpf: ["The engine multiplies annual taxable income by one user-entered rate: estimate=income×rate/100; average rate=tax/income×100. Spanish IRPF law has state and autonomous-community scales and personal factors; this tool does not calculate that progressive system.", "With €30,000 annual taxable income and an entered 15%, the arithmetic estimate is €4,500, or 15% average. This is an input-rate example, not a Spanish return amount or statutory rate.", "Is this my Spanish IRPF liability?", "No. Articles 63 and 74 of Law 35/2006 describe state and regional tax scales, which are not implemented here. Allowances, personal/family minimums, autonomous community and income type are not modeled."],
    severance: ["The engine uses daily basis=monthly salary×12/365 and estimate=daily basis×entered days per service year×service years. Spain's Workers' Statute sets different amounts and caps by termination reason; this tool does not determine the reason, contract date or legal cap.", "At €2,500 monthly, 5 years and an entered 20 days/year, the daily basis is €82.1918 and the estimate is €8,219.18. It is an assumption-based output, not a legal entitlement finding.", "Does entering 20 or 33 days give the legal amount?", "Not necessarily. Articles 53 and 56 set reason-specific rates and monthly caps; transitional treatment may apply to contracts before 12 February 2012. The calculator applies no such caps or contract-date rules."],
  },
  ja: {
    vat: ["入力税率をr%とすると、税抜額のIVA=金額×r/100、税込額=税抜額+IVAです。税込入力では税抜額=合計/(1+r/100)で逆算します。2026-10-28確認のスペイン税務庁は一般税率21%、特定取引の10%・4%・0%を示しますが、本ツールは取引を分類しません。", "税抜€1,000に入力税率21%を適用するとIVAは€210、税込合計は€1,210です。適用率は商品や取引条件で異なる場合があります。", "すべての取引に21%が適用されますか？", "いいえ。特定の取引には10%、4%、0%の税率もあります。本ツールは入力率の算術だけを行い、免税・ゼロ税率・取引地を判定しません。"],
    irpf: ["年次課税所得に入力された単一率を掛けます。推定税額=所得×率/100、平均率=税額/所得×100です。スペインIRPFの国税・自治州税率や個人要素による累進計算は実装されていません。", "年次課税所得€30,000、入力率15%なら算術上の税額は€4,500、平均15%です。申告税額や法定税率ではありません。", "この金額はスペインのIRPF納税額ですか？", "いいえ。法律35/2006条63・74の国税・自治州税率、控除、人的・家族的最低額、居住自治州や所得区分を計算しません。"],
    severance: ["日額基礎=月給×12/365、推計額=日額基礎×入力した勤続年数あたりの日数×勤続年数です。スペイン労働者法の補償は終了理由で日数・上限が異なり、本ツールは理由・契約日・法定上限を判定しません。", "月給€2,500、勤続5年、20日/年を入力すると日額基礎€82.1918、推計€8,219.18です。入力条件による試算で、法的権利額の判定ではありません。", "20日または33日を入力すれば法定額ですか？", "必ずしもそうではありません。労働者法53・56条は事由別の率と月数上限を定め、2012年2月12日より前の契約には経過規定もあり得ます。本ツールは適用しません。"],
  },
  zh: {
    vat: ["输入税率r%后，未税IVA=金额×r/100，含税金额=未税金额+IVA；若输入含税总额，则未税金额=总额/(1+r/100)。西班牙税务局于2026-10-28核对的资料列出一般税率21%，以及特定交易的10%、4%和0%；本工具不会分类交易。", "未税金额€1,000按输入的21%计算，IVA为€210，含税合计€1,210。适用税率可能取决于商品和交易条件。", "所有交易都适用21%吗？", "不是。部分交易适用10%、4%或0%。本计算器只套用输入税率，不判断免税、零税率资格或供应地点。"],
    irpf: ["引擎将年应税收入乘以用户输入的单一税率：估算税额=收入×税率/100，平均税率=税额/收入×100。西班牙IRPF的国家与自治区税阶及个人因素不由此工具计算。", "年应税收入€30,000，输入15%，算术结果为€4,500，平均15%。这不是西班牙申报税额或法定税率。", "这是我的西班牙IRPF应缴税额吗？", "不是。《第35/2006号法律》第63、74条涉及国家及自治区税阶；本工具未实现这些税阶，也未考虑扣除、个人家庭免税额、居住自治区和收入类别。"],
    severance: ["引擎按日工资基数=月薪×12/365、估算额=日基数×输入的每年工龄天数×工龄年数计算。西班牙《劳动者法》按终止原因规定不同天数和上限；本工具不判断原因、合同日期或法定上限。", "月薪€2,500、工龄5年、输入20天/年时，日基数€82.1918，估算€8,219.18。这只是输入假设下的结果，不是法律权利认定。", "输入20天或33天就等于法定金额吗？", "不能这样认定。《劳动者法》第53、56条按原因设定比例和月数上限；2012年2月12日前的合同可能适用过渡规则。本工具不应用这些条件。"],
  },
  es: {
    vat: ["Con el tipo introducido r%, IVA sobre base=base×r/100 y total=base+IVA. Si el importe ya incluye IVA, base=total/(1+r/100). La AEAT, consultada el 28-10-2026, indica un tipo general del 21% y tipos del 10%, 4% y 0% para operaciones determinadas; esta herramienta no clasifica operaciones.", "Una base de 1.000 € al 21% introducido genera 210 € de IVA y 1.210 € en total. El tipo aplicable puede depender del bien y de la operación.", "¿El 21% se aplica a todas las operaciones?", "No. La AEAT contempla tipos reducidos del 10% y 4%, y el 0% para determinadas operaciones. La calculadora solo aplica el tipo elegido; no determina exenciones, tipo cero ni lugar de tributación."],
    irpf: ["El motor multiplica la base anual introducida por un único tipo elegido: estimación=base×tipo/100; tipo medio=cuota/base×100. El IRPF español combina escalas estatal y autonómica y circunstancias personales, que esta herramienta no calcula.", "Con una base anual de 30.000 € y un 15% introducido, el resultado aritmético es 4.500 €, un 15% medio. No es una cuota de declaración ni un tipo legal.", "¿Es mi cuota real del IRPF español?", "No. Los artículos 63 y 74 de la Ley 35/2006 contemplan escalas estatal y autonómica. Aquí no se calculan mínimos, reducciones, deducciones, comunidad autónoma ni clases de renta."],
    severance: ["El motor usa salario diario=salario mensual×12/365 y estimación=salario diario×días introducidos por año×años de servicio. El Estatuto de los Trabajadores establece indemnizaciones y topes distintos según la causa; la herramienta no identifica la causa, fecha del contrato ni límite legal.", "Con 2.500 € al mes, 5 años y 20 días/año introducidos, la base diaria es 82,1918 € y el cálculo da 8.219,18 €. Es una hipótesis matemática, no la determinación de un derecho legal.", "¿Introducir 20 o 33 días da la indemnización legal?", "No necesariamente. Los artículos 53 y 56 fijan reglas y topes mensuales por causa; los contratos anteriores al 12-02-2012 pueden tener régimen transitorio. La calculadora no aplica esos límites."],
  },
  "pt-br": {
    vat: ["Com a alíquota informada r%, IVA sobre o valor líquido=valor×r/100 e total=líquido+IVA. Se o valor já inclui IVA, líquido=total/(1+r/100). A Agência Tributária espanhola, consultada em 28/10/2026, informa taxa geral de 21% e taxas de 10%, 4% e 0% para operações específicas; a ferramenta não classifica a operação.", "Uma base de €1.000 a 21% gera €210 de IVA e total de €1.210. A taxa aplicável pode depender do produto e da operação.", "21% vale para toda operação?", "Não. Há operações específicas com 10%, 4% ou 0%. A calculadora aplica apenas a taxa escolhida e não define isenção, alíquota zero ou local da operação."],
    irpf: ["O motor multiplica a renda tributável anual por uma única taxa informada: estimativa=renda×taxa/100; taxa média=imposto/renda×100. O IRPF espanhol combina escalas estatal e autonômica e fatores pessoais, que não são calculados aqui.", "Com renda anual tributável de €30.000 e taxa informada de 15%, o resultado aritmético é €4.500 (média de 15%). Não é imposto declarado nem alíquota legal.", "Este é meu imposto devido na Espanha?", "Não. Os artigos 63 e 74 da Lei 35/2006 tratam das escalas estatal e autonômica; deduções, mínimos pessoais/familiares, comunidade e tipo de renda não são modelados."],
    severance: ["O motor usa salário diário=salário mensal×12/365 e estimativa=base diária×dias informados por ano de serviço×anos. O Estatuto dos Trabalhadores prevê regras e limites diferentes conforme a causa; a ferramenta não identifica causa, data do contrato ou teto legal.", "Salário de €2.500 por mês, 5 anos e 20 dias/ano informados produzem base diária de €82,1918 e estimativa de €8.219,18. É um cenário matemático, não a definição de um direito legal.", "Informar 20 ou 33 dias garante o valor legal?", "Não. Os artigos 53 e 56 preveem taxas e limites mensais conforme a causa, e contratos anteriores a 12/02/2012 podem seguir regras transitórias. A calculadora não aplica essas condições."],
  },
  de: {
    vat: ["Bei eingegebenem Satz r% gilt: IVA auf netto=Netto×r/100, Brutto=Netto+IVA. Bei einem Bruttopreis ist Netto=Gesamt/(1+r/100). Die spanische Steuerbehörde nennt laut Prüfung vom 28.10.2026 21% als allgemeinen Satz sowie 10%, 4% und 0% für bestimmte Umsätze; das Tool ordnet Umsätze nicht ein.", "1.000 € netto zu den eingegebenen 21% ergeben 210 € IVA und 1.210 € brutto. Der passende Satz hängt unter anderem von Ware und Umsatz ab.", "Gelten 21% für jeden Umsatz?", "Nein. Für bestimmte Umsätze gelten 10%, 4% oder 0%. Der Rechner wendet nur den eingegebenen Satz an und beurteilt weder Befreiung noch Nullsatz oder Leistungsort."],
    irpf: ["Die Engine multipliziert das eingegebene jährliche steuerpflichtige Einkommen mit einem einzigen Benutzersatz: Schätzung=Einkommen×Satz/100; Durchschnittssatz=Steuer/Einkommen×100. Das spanische IRPF umfasst staatliche und regionale Tarifstufen und persönliche Faktoren, die hier nicht berechnet werden.", "Bei 30.000 € Jahreseinkommen und eingegebenen 15% ergibt die reine Rechnung 4.500 € bzw. 15% im Durchschnitt. Das ist weder Steuerbescheid noch gesetzlicher Satz.", "Ist das meine spanische IRPF-Steuerschuld?", "Nein. Artikel 63 und 74 des Gesetzes 35/2006 sehen staatliche und regionale Tarife vor. Freibeträge, persönliche/familiäre Mindestbeträge, Region und Einkunftsart fehlen im Modell."],
    severance: ["Die Engine rechnet Tagesbasis=Monatsgehalt×12/365 und Schätzung=Tagesbasis×eingegebene Tage je Dienstjahr×Dienstjahre. Das spanische Arbeitnehmerstatut unterscheidet Entschädigung und Obergrenzen nach Beendigungsgrund; Grund, Vertragsdatum und gesetzliche Obergrenze werden nicht geprüft.", "Bei 2.500 € Monatsgehalt, 5 Jahren und eingegebenen 20 Tagen/Jahr beträgt die Tagesbasis 82,1918 € und die Schätzung 8.219,18 €. Das ist eine Rechenannahme, keine Feststellung eines Rechtsanspruchs.", "Liefert die Eingabe von 20 oder 33 Tagen den gesetzlichen Betrag?", "Nicht zwingend. Artikel 53 und 56 setzen grundabhängige Sätze und Monatsobergrenzen; für Verträge vor dem 12.02.2012 können Übergangsregeln gelten. Der Rechner wendet diese Regeln nicht an."],
  },
  fr: {
    vat: ["Au taux saisi r %, TVA sur le montant HT=montant×r/100 et TTC=HT+TVA. Pour un montant TTC, HT=total/(1+r/100). Vérifiée le 28/10/2026, l’Agence fiscale espagnole indique 21 % au taux général et 10 %, 4 % ou 0 % pour certaines opérations; cet outil ne classe pas les opérations.", "Une base de 1 000 € au taux saisi de 21 % donne 210 € de TVA et 1 210 € TTC. Le taux applicable dépend notamment du bien et de l’opération.", "Le taux de 21 % s’applique-t-il partout ?", "Non. Certaines opérations relèvent de 10 %, 4 % ou 0 %. L’outil applique seulement le taux choisi et ne détermine ni exonération, ni taux zéro, ni lieu d’imposition."],
    irpf: ["Le moteur applique un taux unique saisi au revenu annuel imposable: estimation=revenu×taux/100; taux moyen=impôt/revenu×100. L’IRPF espagnol comprend des barèmes d’État et des communautés autonomes ainsi que des facteurs personnels non calculés ici.", "Pour 30 000 € de revenu annuel et un taux saisi de 15 %, le calcul arithmétique donne 4 500 €, soit 15 % en moyenne. Ce n’est ni une déclaration ni un taux légal.", "Est-ce mon impôt IRPF dû en Espagne ?", "Non. Les articles 63 et 74 de la loi 35/2006 prévoient des barèmes étatiques et autonomiques. Abattements, minimums personnels/familiaux, communauté et nature du revenu ne sont pas modélisés."],
    severance: ["Le moteur calcule base journalière=salaire mensuel×12/365, puis estimation=base journalière×jours saisis par année×années de service. Le statut espagnol prévoit des règles et plafonds selon le motif; l’outil ne connaît ni le motif, ni la date du contrat, ni le plafond légal.", "Avec 2 500 € par mois, 5 ans et 20 jours/an saisis, la base est de 82,1918 € par jour et l’estimation de 8 219,18 €. C’est une hypothèse de calcul, pas la reconnaissance d’un droit.", "Saisir 20 ou 33 jours donne-t-il le montant légal ?", "Pas nécessairement. Les articles 53 et 56 fixent des taux et plafonds mensuels selon le motif; les contrats antérieurs au 12/02/2012 peuvent relever de règles transitoires. Le calculateur ne les applique pas."],
  },
  vi: {
    vat: ["Với thuế suất nhập r%, IVA trên giá chưa thuế=giá×r/100 và tổng=giá chưa thuế+IVA. Nếu giá đã gồm thuế, giá chưa thuế=tổng/(1+r/100). Cơ quan Thuế Tây Ban Nha được kiểm tra ngày 28/10/2026 nêu mức chung 21% và 10%, 4%, 0% cho một số giao dịch; công cụ không phân loại hàng hóa.", "Giá chưa thuế €1.000 ở mức nhập 21% tạo IVA €210, tổng €1.210. Thuế suất thực tế phụ thuộc hàng hóa và giao dịch.", "Mọi giao dịch đều chịu 21% phải không?", "Không. Một số giao dịch áp dụng 10%, 4% hoặc 0%. Công cụ chỉ tính theo mức bạn nhập, không xác định miễn thuế, thuế suất 0% hay nơi cung cấp."],
    irpf: ["Động cơ nhân thu nhập chịu thuế năm với một tỷ lệ do người dùng nhập: ước tính=thu nhập×tỷ lệ/100; tỷ lệ trung bình=thuế/thu nhập×100. IRPF Tây Ban Nha có biểu thuế quốc gia, vùng tự trị và yếu tố cá nhân mà công cụ không tính.", "Thu nhập chịu thuế năm €30.000 với tỷ lệ nhập 15% cho kết quả số học €4.500, trung bình 15%. Đây không phải số thuế khai báo hay thuế suất pháp định.", "Đây có phải số thuế IRPF tôi phải nộp không?", "Không. Điều 63 và 74 Luật 35/2006 quy định biểu thuế quốc gia và vùng. Công cụ bỏ qua giảm trừ, mức tối thiểu cá nhân/gia đình, vùng cư trú và loại thu nhập."],
    severance: ["Động cơ tính cơ sở ngày=lương tháng×12/365, rồi ước tính=cơ sở ngày×số ngày mỗi năm nhập vào×số năm làm việc. Luật Lao động Tây Ban Nha quy định mức và trần khác nhau theo lý do chấm dứt; công cụ không xét lý do, ngày hợp đồng hoặc trần pháp lý.", "Lương tháng €2.500, 5 năm và nhập 20 ngày/năm cho cơ sở €82,1918/ngày, ước tính €8.219,18. Đây là phép tính theo giả định, không xác nhận quyền lợi pháp lý.", "Nhập 20 hoặc 33 ngày có ra đúng mức luật định không?", "Không thể khẳng định. Điều 53 và 56 quy định mức và trần theo tháng tùy lý do; hợp đồng trước 12/02/2012 có thể theo quy tắc chuyển tiếp. Công cụ không áp dụng chúng."],
  },
  id: {
    vat: ["Dengan tarif masukan r%, IVA atas nilai bersih=nilai×r/100 dan total=bersih+IVA. Jika jumlah sudah termasuk pajak, nilai bersih=total/(1+r/100). Per 28-10-2026, Badan Pajak Spanyol menyebut 21% sebagai tarif umum dan 10%, 4%, atau 0% untuk transaksi tertentu; alat ini tidak mengklasifikasikan transaksi.", "Nilai bersih €1.000 pada 21% menghasilkan IVA €210 dan total €1.210. Tarif yang berlaku dapat bergantung pada barang dan transaksi.", "Apakah 21% berlaku untuk semua transaksi?", "Tidak. Transaksi tertentu dapat memakai 10%, 4%, atau 0%. Kalkulator hanya menerapkan tarif pilihan dan tidak menentukan pembebasan, tarif nol, atau tempat pajak."],
    irpf: ["Mesin mengalikan penghasilan kena pajak tahunan dengan satu tarif yang dimasukkan: estimasi=penghasilan×tarif/100; tarif rata-rata=pajak/penghasilan×100. IRPF Spanyol memiliki skala negara dan wilayah otonom serta faktor pribadi yang tidak dihitung alat ini.", "Penghasilan kena pajak tahunan €30.000 dengan tarif masukan 15% menghasilkan €4.500 secara aritmetis, rata-rata 15%. Ini bukan jumlah pelaporan atau tarif hukum.", "Apakah ini pajak IRPF Spanyol yang harus saya bayar?", "Bukan. Pasal 63 dan 74 UU 35/2006 mencakup skala negara dan wilayah. Pengurang, minimum pribadi/keluarga, wilayah domisili, dan jenis penghasilan tidak dimodelkan."],
    severance: ["Mesin memakai dasar harian=gaji bulanan×12/365, lalu estimasi=dasar harian×hari per masa kerja yang dimasukkan×tahun masa kerja. Statuta Pekerja Spanyol menetapkan tarif dan batas berbeda menurut alasan pemutusan; alat tidak memeriksa alasan, tanggal kontrak, atau batas hukum.", "Gaji bulanan €2.500, masa kerja 5 tahun, dan masukan 20 hari/tahun menghasilkan dasar €82,1918 per hari dan estimasi €8.219,18. Ini skenario hitung, bukan penetapan hak hukum.", "Apakah 20 atau 33 hari yang dimasukkan pasti menghasilkan jumlah hukum?", "Belum tentu. Pasal 53 dan 56 menetapkan tarif serta batas bulanan menurut alasan; kontrak sebelum 12-02-2012 dapat memiliki aturan transisi. Kalkulator tidak menerapkannya."],
  },
  th: {
    vat: ["เมื่อใส่อัตรา r% ภาษี IVA จากราคาก่อนภาษี=ราคา×r/100 และราคารวม=ราคาก่อนภาษี+IVA หากยอดรวมภาษีแล้ว ราคาก่อนภาษี=ยอดรวม/(1+r/100) หน่วยงานภาษีสเปนที่ตรวจเมื่อ 28-10-2026 ระบุอัตราทั่วไป 21% และ 10%, 4%, 0% สำหรับบางรายการ เครื่องมือนี้ไม่จัดประเภทสินค้า", "ราคาก่อนภาษี €1,000 ที่อัตรา 21% ได้ IVA €210 รวม €1,210 อัตราที่ใช้จริงอาจขึ้นกับสินค้าและธุรกรรม", "ทุกธุรกรรมใช้อัตรา 21% หรือไม่?", "ไม่ บางธุรกรรมใช้อัตรา 10%, 4% หรือ 0% เครื่องมือนี้คำนวณตามอัตราที่กรอกเท่านั้น ไม่วินิจฉัยการยกเว้น สินค้าอัตราศูนย์ หรือสถานที่จัดเก็บภาษี"],
    irpf: ["ระบบคูณรายได้ที่ต้องเสียภาษีรายปีด้วยอัตราเดียวที่ผู้ใช้กรอก: ภาษีประมาณ=รายได้×อัตรา/100; อัตราเฉลี่ย=ภาษี/รายได้×100 IRPF สเปนมีขั้นภาษีระดับรัฐและแคว้นรวมถึงปัจจัยส่วนบุคคลซึ่งเครื่องมือนี้ไม่ได้คำนวณ", "รายได้ที่ต้องเสียภาษี €30,000 และกรอก 15% ได้ผลคำนวณ €4,500 หรือเฉลี่ย 15% นี่ไม่ใช่ยอดยื่นภาษีหรืออัตราตามกฎหมาย", "นี่คือภาษี IRPF ที่ต้องจ่ายจริงหรือไม่?", "ไม่ กฎหมาย 35/2006 มาตรา 63 และ 74 กล่าวถึงขั้นภาษีระดับรัฐและแคว้น เครื่องมือนี้ไม่คำนวณค่าลดหย่อน ขั้นต่ำบุคคล/ครอบครัว แคว้นที่พำนัก หรือชนิดรายได้"],
    severance: ["ระบบใช้ฐานรายวัน=เงินเดือนต่อเดือน×12/365 และประมาณการ=ฐานรายวัน×จำนวนวันที่กรอกต่อปีงาน×จำนวนปีทำงาน กฎหมายแรงงานสเปนกำหนดอัตราและเพดานต่างกันตามเหตุเลิกจ้าง เครื่องมือนี้ไม่ตรวจเหตุ วันที่ทำสัญญา หรือเพดานตามกฎหมาย", "เงินเดือน €2,500 ต่อเดือน ทำงาน 5 ปี และกรอก 20 วัน/ปี ได้ฐาน €82.1918 ต่อวันและประมาณการ €8,219.18 เป็นผลตามสมมติฐาน ไม่ใช่การวินิจฉัยสิทธิ", "กรอก 20 หรือ 33 วันแล้วเป็นยอดตามกฎหมายหรือไม่?", "ไม่จำเป็น มาตรา 53 และ 56 กำหนดอัตราและเพดานรายเดือนตามเหตุ และสัญญาก่อน 12-02-2012 อาจมีบทเฉพาะกาล เครื่องมือนี้ไม่ใช้เงื่อนไขเหล่านั้น"],
  },
  "zh-tw": {
    vat: ["輸入稅率 r% 後，未稅 IVA=金額×r/100，含稅總額=未稅金額+IVA；若輸入含稅總額，未稅金額=總額/(1+r/100)。西班牙稅務局於 2026-10-28 查核資料列一般稅率 21%，特定交易另有 10%、4% 與 0%；本工具不判斷交易類別。", "未稅 €1,000 以輸入的 21% 計算，IVA 為 €210，含稅合計 €1,210。實際稅率可能取決於商品及交易。", "所有交易都適用 21% 嗎？", "不是。特定交易可能適用 10%、4% 或 0%。本計算器只套用輸入稅率，不判斷免稅、零稅率或課稅地點。"],
    irpf: ["引擎將年度應稅所得乘以使用者輸入的單一稅率：估算稅額=所得×稅率/100；平均稅率=稅額/所得×100。西班牙 IRPF 的國家與自治區級級距及個人因素並未由此工具計算。", "年度應稅所得 €30,000、輸入 15%，算術結果為 €4,500，平均 15%。這不是西班牙申報稅額或法定稅率。", "這是我在西班牙應繳的 IRPF 嗎？", "不是。第 35/2006 號法律第 63、74 條涉及國家與自治區稅率；本工具未計入扣除、個人與家庭最低額、居住自治區及所得類別。"],
    severance: ["引擎按日薪基礎=月薪×12/365、估算額=日薪基礎×輸入的每年年資天數×年資計算。西班牙《勞工法》依終止原因規定不同金額及上限；工具不判斷原因、合約日期或法定上限。", "月薪 €2,500、年資 5 年、輸入 20 天/年時，日薪基礎為 €82.1918，估算 €8,219.18。這是依輸入假設的試算，不是法律權利判定。", "輸入 20 或 33 天就等於法定金額嗎？", "不一定。第 53、56 條依原因設定費率與月數上限；2012-02-12 前的合約可能適用過渡規定。本計算器不套用這些條件。"],
  },
  it: {
    vat: ["Con aliquota inserita r%, IVA sul netto=importo×r/100 e totale=netto+IVA. Per un totale IVA inclusa, netto=totale/(1+r/100). L’Agenzia tributaria spagnola, consultata il 28/10/2026, indica 21% come aliquota generale e 10%, 4% o 0% per operazioni specifiche; lo strumento non classifica le operazioni.", "Una base netta di 1.000 € al 21% inserito produce 210 € di IVA e 1.210 € totali. L’aliquota applicabile può dipendere da bene e operazione.", "Il 21% vale per ogni operazione?", "No. Per alcune operazioni valgono 10%, 4% o 0%. Il calcolatore applica solo l’aliquota scelta e non stabilisce esenzioni, aliquota zero o luogo di imposizione."],
    irpf: ["Il motore moltiplica il reddito imponibile annuo inserito per un’unica aliquota scelta: stima=reddito×aliquota/100; aliquota media=imposta/reddito×100. L’IRPF spagnolo ha scaglioni statali e autonomici e fattori personali non calcolati qui.", "Con reddito imponibile annuo di 30.000 € e aliquota inserita del 15%, il calcolo aritmetico dà 4.500 €, media 15%. Non è l’imposta dichiarata né un’aliquota legale.", "È la mia imposta IRPF effettiva in Spagna?", "No. Gli articoli 63 e 74 della legge 35/2006 prevedono scaglioni statali e autonomici. Deduzioni, minimi personali/familiari, comunità di residenza e tipo di reddito non sono modellati."],
    severance: ["Il motore usa base giornaliera=stipendio mensile×12/365 e stima=base giornaliera×giorni inseriti per anno di servizio×anni. Lo Statuto dei lavoratori spagnolo prevede regole e massimali diversi per causa; lo strumento non verifica causa, data del contratto o limite legale.", "Con 2.500 € mensili, 5 anni e 20 giorni/anno inseriti, la base giornaliera è 82,1918 € e la stima 8.219,18 €. È uno scenario aritmetico, non l’accertamento di un diritto.", "Inserire 20 o 33 giorni dà l’importo legale?", "Non necessariamente. Gli articoli 53 e 56 fissano tassi e massimali mensili secondo la causa; i contratti anteriori al 12/02/2012 possono avere regole transitorie. Il calcolatore non le applica."],
  },
  nl: {
    vat: ["Bij ingevoerd tarief r% is IVA over netto=bedrag×r/100 en bruto=netto+IVA. Bij een bedrag inclusief IVA geldt netto=totaal/(1+r/100). De Spaanse Belastingdienst vermeldt volgens controle op 28-10-2026 21% als algemeen tarief en 10%, 4% of 0% voor bepaalde transacties; deze tool classificeert niets.", "Een netto bedrag van €1.000 tegen de ingevoerde 21% geeft €210 IVA en €1.210 totaal. Het toepasselijke tarief kan afhangen van product en transactie.", "Geldt 21% voor iedere transactie?", "Nee. Voor specifieke transacties bestaan 10%, 4% en 0%. Deze calculator past alleen het gekozen percentage toe en bepaalt geen vrijstelling, nultarief of plaats van heffing."],
    irpf: ["De engine vermenigvuldigt het ingevoerde jaarlijkse belastbare inkomen met één opgegeven tarief: schatting=inkomen×tarief/100; gemiddeld tarief=belasting/inkomen×100. Spaanse IRPF kent staats- en regionale schijven en persoonlijke factoren die deze tool niet berekent.", "Bij €30.000 jaarinkomen en een ingevoerd tarief van 15% is de rekenschatting €4.500, gemiddeld 15%. Dit is geen Spaanse aangifte-uitkomst of wettelijk tarief.", "Is dit mijn verschuldigde Spaanse IRPF?", "Nee. Artikelen 63 en 74 van Wet 35/2006 bevatten staats- en regionale schalen. Aftrekposten, persoonlijke/familiale minima, regio en soort inkomen zijn niet gemodelleerd."],
    severance: ["De engine gebruikt dagbasis=maandsalaris×12/365 en schatting=dagbasis×ingevoerde dagen per dienstjaar×dienstjaren. Het Spaanse Arbeidersstatuut kent verschillende vergoedingen en maxima per beëindigingsgrond; reden, contractdatum en wettelijk maximum worden niet vastgesteld.", "Bij €2.500 per maand, 5 dienstjaren en ingevoerd 20 dagen/jaar is de dagbasis €82,1918 en de schatting €8.219,18. Dit is een rekenaanname, geen vaststelling van een wettelijk recht.", "Levert invoer van 20 of 33 dagen het wettelijke bedrag op?", "Niet per se. Artikelen 53 en 56 stellen grondafhankelijke tarieven en maandmaxima; contracten vóór 12-02-2012 kunnen overgangsregels hebben. De calculator past deze regels niet toe."],
  },
  hi: {
    vat: ["दर्ज दर r% पर शुद्ध राशि का IVA=राशि×r/100 और कुल=शुद्ध+IVA है। कर-सहित कुल से शुद्ध राशि=कुल/(1+r/100) निकलती है। 28-10-2026 को जाँची गई स्पेनिश कर एजेंसी की जानकारी में सामान्य दर 21% और कुछ लेनदेन के लिए 10%, 4% तथा 0% हैं; यह टूल लेनदेन का वर्गीकरण नहीं करता।", "€1,000 शुद्ध राशि पर दर्ज 21% से IVA €210 और कुल €1,210 है। लागू दर वस्तु और लेनदेन पर निर्भर हो सकती है।", "क्या हर लेनदेन पर 21% लगता है?", "नहीं। कुछ लेनदेन पर 10%, 4% या 0% लागू होता है। यह कैलकुलेटर केवल चुनी दर लगाता है; छूट, शून्य-दर या आपूर्ति-स्थान तय नहीं करता।"],
    irpf: ["इंजन वार्षिक करयोग्य आय पर उपयोगकर्ता की एक दर लगाता है: अनुमान=आय×दर/100; औसत दर=कर/आय×100। स्पेनिश IRPF में राष्ट्रीय और स्वायत्त-क्षेत्रीय दर-सीढ़ियाँ तथा व्यक्तिगत स्थितियाँ हैं, जिन्हें यह टूल नहीं निकालता।", "€30,000 वार्षिक करयोग्य आय पर दर्ज 15% से गणितीय अनुमान €4,500 और औसत 15% है। यह कर-रिटर्न राशि या वैधानिक दर नहीं है।", "क्या यह मेरा वास्तविक स्पेनिश IRPF है?", "नहीं। कानून 35/2006 के अनुच्छेद 63 और 74 राष्ट्रीय व क्षेत्रीय दरों को शामिल करते हैं; कटौतियाँ, व्यक्तिगत/पारिवारिक न्यूनतम, स्वायत्त क्षेत्र और आय का प्रकार यहाँ मॉडल नहीं हैं।"],
    severance: ["इंजन दैनिक आधार=मासिक वेतन×12/365 और अनुमान=दैनिक आधार×दर्ज प्रति सेवा-वर्ष दिन×सेवा-वर्ष लगाता है। स्पेनिश श्रमिक क़ानून समाप्ति के कारण के अनुसार अलग राशि और सीमा रखता है; यह टूल कारण, अनुबंध-तिथि या कानूनी सीमा नहीं जाँचता।", "€2,500 मासिक वेतन, 5 वर्ष और दर्ज 20 दिन/वर्ष पर दैनिक आधार €82.1918 और अनुमान €8,219.18 है। यह इनपुट-आधारित गणना है, कानूनी अधिकार का निर्धारण नहीं।", "क्या 20 या 33 दिन डालने से कानूनी राशि मिलती है?", "ज़रूरी नहीं। अनुच्छेद 53 और 56 कारण के अनुसार दर व मासिक सीमा तय करते हैं; 12-02-2012 से पहले के अनुबंधों पर संक्रमण नियम हो सकते हैं। कैलकुलेटर इन्हें लागू नहीं करता।"],
  },
  ru: {
    vat: ["При введенной ставке r% НДС на сумму без налога=сумма×r/100, итог=сумма+НДС. Если сумма уже включает налог, база=итог/(1+r/100). Налоговое агентство Испании, проверенное 28.10.2026, указывает общую ставку 21% и 10%, 4% или 0% для отдельных операций; инструмент не определяет категорию операции.", "При базе €1 000 и введенных 21% НДС равен €210, итог €1 210. Применимая ставка зависит от товара и операции.", "Ставка 21% действует для всех операций?", "Нет. Для отдельных операций применяются 10%, 4% или 0%. Калькулятор только использует введенную ставку и не определяет освобождение, нулевую ставку или место налогообложения."],
    irpf: ["Алгоритм умножает годовой налогооблагаемый доход на одну введенную ставку: оценка=доход×ставка/100; средняя ставка=налог/доход×100. Испанский IRPF включает государственные и региональные шкалы и личные обстоятельства, которые здесь не рассчитываются.", "При доходе €30 000 и введенных 15% арифметическая оценка равна €4 500, средняя ставка 15%. Это не сумма декларации и не законная ставка.", "Это мой фактический налог IRPF в Испании?", "Нет. Статьи 63 и 74 Закона 35/2006 предусматривают государственные и региональные шкалы. Вычеты, личный и семейный минимум, регион и вид дохода не учтены."],
    severance: ["Алгоритм берет дневную базу=месячная зарплата×12/365 и оценку=дневная база×введенные дни за год стажа×годы стажа. Испанский статут работников устанавливает разные суммы и пределы по основанию увольнения; калькулятор не проверяет основание, дату договора или законный максимум.", "При зарплате €2 500 в месяц, стаже 5 лет и введенных 20 днях/год дневная база равна €82,1918, оценка — €8 219,18. Это расчет по допущению, а не признание права.", "Дают ли 20 или 33 дня законную сумму?", "Не обязательно. Статьи 53 и 56 устанавливают ставки и пределы в месяцах по основанию; для договоров до 12.02.2012 могут действовать переходные правила. Калькулятор их не применяет."],
  },
  tr: {
    vat: ["Girilen r% oranında net tutarın IVA'sı=tutar×r/100, brüt=tutar+IVA olur. Tutar vergi dahilse net=toplam/(1+r/100) şeklinde ayrıştırılır. 28.10.2026'da kontrol edilen İspanya Vergi Dairesi genel oranı %21; belirli işlemler için %10, %4 ve %0 olarak bildirir. Araç işlemi sınıflandırmaz.", "€1.000 net tutara girilen %21 uygulanınca €210 IVA ve €1.210 toplam çıkar. Uygulanacak oran ürün ve işleme göre değişebilir.", "%21 her işlem için geçerli mi?", "Hayır. Belirli işlemlerde %10, %4 veya %0 olabilir. Hesaplayıcı yalnızca seçilen oranı uygular; istisna, sıfır oranı ya da vergilendirme yerini belirlemez."],
    irpf: ["Motor, yıllık vergiye tabi geliri kullanıcının girdiği tek oranla çarpar: tahmin=gelir×oran/100; ortalama oran=vergi/gelir×100. İspanyol IRPF sistemi devlet ve özerk bölge tarifeleri ile kişisel unsurlar içerir; araç bunları hesaplamaz.", "€30.000 yıllık vergiye tabi gelir ve girilen %15, aritmetik olarak €4.500, ortalama %15 verir. Bu beyanname tutarı veya yasal oran değildir.", "Bu, İspanya'da ödeyeceğim gerçek IRPF mi?", "Hayır. 35/2006 sayılı Kanun'un 63 ve 74. maddelerindeki devlet ve bölge tarifeleri uygulanmaz; indirimler, kişisel/ailevi asgari tutarlar, ikamet bölgesi ve gelir türü modellenmez."],
    severance: ["Motor günlük taban=aylık ücret×12/365, tahmin=günlük taban×girilen hizmet yılı başına gün×hizmet yılı kullanır. İspanya İşçi Statüsü fesih nedenine göre farklı tutarlar ve tavanlar koyar; araç nedeni, sözleşme tarihini veya yasal tavanı belirlemez.", "Aylık €2.500 ücret, 5 yıl ve girilen 20 gün/yıl ile günlük taban €82,1918, tahmin €8.219,18 olur. Bu varsayımsal hesaptır, yasal hak tespiti değildir.", "20 veya 33 gün girmek yasal tutarı verir mi?", "Her zaman değil. 53. ve 56. maddeler nedene göre oran ve aylık tavanlar belirler; 12.02.2012 öncesi sözleşmelerde geçiş hükümleri olabilir. Hesaplayıcı bunları uygulamaz."],
  },
  pl: {
    vat: ["Przy wpisanej stawce r% IVA od kwoty netto=kwota×r/100, a brutto=netto+IVA. Dla kwoty brutto netto=całość/(1+r/100). Hiszpańska Agencja Podatkowa, sprawdzona 28.10.2026, podaje 21% jako stawkę ogólną oraz 10%, 4% i 0% dla wybranych transakcji; narzędzie ich nie klasyfikuje.", "Netto 1 000 € przy wpisanych 21% daje 210 € IVA i 1 210 € brutto. Właściwa stawka zależy m.in. od towaru i transakcji.", "Czy 21% dotyczy każdej transakcji?", "Nie. Wybrane transakcje podlegają stawkom 10%, 4% lub 0%. Kalkulator stosuje tylko podaną stawkę i nie ustala zwolnienia, stawki zerowej ani miejsca opodatkowania."],
    irpf: ["Silnik mnoży roczny dochód podlegający opodatkowaniu przez jedną wpisaną stawkę: szacunek=dochód×stawka/100; stawka średnia=podatek/dochód×100. Hiszpański IRPF obejmuje skale państwowe i wspólnot autonomicznych oraz czynniki osobiste, których narzędzie nie liczy.", "Przy dochodzie 30 000 € i wpisanych 15% wynik arytmetyczny to 4 500 €, średnio 15%. To nie kwota deklaracji ani stawka ustawowa.", "Czy to mój należny hiszpański IRPF?", "Nie. Artykuły 63 i 74 ustawy 35/2006 opisują skale krajowe i regionalne. Ulgi, minimum osobiste/rodzinne, wspólnota zamieszkania i rodzaj dochodu nie są modelowane."],
    severance: ["Silnik przyjmuje podstawę dzienną=miesięczna pensja×12/365, a szacunek=podstawa dzienna×wpisane dni za rok stażu×lata stażu. Hiszpański statut pracowników różnicuje świadczenia i limity według przyczyny; narzędzie nie ustala przyczyny, daty umowy ani limitu prawnego.", "Przy 2 500 € miesięcznie, 5 latach i wpisanych 20 dniach/rok podstawa dzienna wynosi 82,1918 €, a wynik 8 219,18 €. To obliczenie założeń, nie ustalenie prawa.", "Czy wpisanie 20 lub 33 dni daje kwotę ustawową?", "Nie zawsze. Artykuły 53 i 56 określają stawki i limity miesięczne zależnie od przyczyny; dla umów sprzed 12.02.2012 mogą obowiązywać przepisy przejściowe. Kalkulator ich nie stosuje."],
  },
  fil: {
    vat: ["Sa inilagay na rate na r%, IVA sa netong halaga=halaga×r/100 at kabuuan=neto+IVA. Kung kasama na ang buwis, neto=kabuuan/(1+r/100). Ayon sa Spanish Tax Agency na sinuri noong 28-10-2026, 21% ang pangkalahatang rate at may 10%, 4%, o 0% para sa ilang transaksyon; hindi inuuri ng tool ang supply.", "Ang €1,000 na neto sa inilagay na 21% ay may €210 IVA at €1,210 kabuuan. Maaaring depende ang aktuwal na rate sa produkto at transaksyon.", "21% ba ang rate sa lahat ng transaksyon?", "Hindi. May ilang transaksyong gumagamit ng 10%, 4%, o 0%. Inilalapat lang ng calculator ang piniling rate; hindi nito tinutukoy ang exemption, zero-rating, o lugar ng pagbubuwis."],
    irpf: ["Minumultiply ng engine ang taunang taxable income sa iisang rate na inilagay: tantiya=kita×rate/100; average rate=buwis/kita×100. May pambansa at rehiyonal na bracket at personal na salik ang IRPF ng Spain na hindi kinukuwenta rito.", "Sa taunang taxable income na €30,000 at inilagay na 15%, €4,500 ang arithmetic estimate o 15% average. Hindi ito halaga sa tax return o legal na rate.", "Ito ba ang aktuwal kong IRPF na babayaran sa Spain?", "Hindi. Saklaw ng Artikulo 63 at 74 ng Batas 35/2006 ang national at regional scales. Hindi kasama ang deductions, personal/family minimums, autonomous community, at uri ng kita."],
    severance: ["Gamit ng engine ang daily basis=buwanang sahod×12/365 at estimate=daily basis×inilagay na araw kada taon ng serbisyo×taon ng serbisyo. Iba-iba ang indemnity at cap sa Spanish Workers' Statute ayon sa dahilan ng pagwawakas; hindi sinusuri ng tool ang dahilan, petsa ng kontrata, o legal cap.", "Sa €2,500 buwanang sahod, 5 taon at inilagay na 20 araw/taon, €82.1918 ang daily basis at €8,219.18 ang estimate. Scenario math ito, hindi pagkilala sa legal na karapatan.", "Legal na halaga ba ang 20 o 33 araw?", "Hindi palagi. Nagtatakda ang Artikulo 53 at 56 ng rates at monthly caps ayon sa dahilan; maaaring may transitional rules ang kontratang nauna sa 12-02-2012. Hindi ito inilalapat ng calculator."],
  },
  bn: {
    vat: ["দেওয়া r% হারে কর-পূর্ব IVA=অঙ্ক×r/100 এবং মোট=কর-পূর্ব অঙ্ক+IVA। কর-সহ মোট থেকে কর-পূর্ব অঙ্ক=মোট/(1+r/100)। 28-10-2026-এ যাচাই করা স্পেনের কর সংস্থা সাধারণ 21% এবং নির্দিষ্ট লেনদেনে 10%, 4% বা 0% জানায়; এই টুল পণ্য শ্রেণিবদ্ধ করে না।", "€1,000 কর-পূর্ব অঙ্কে দেওয়া 21% প্রয়োগে IVA €210, মোট €1,210। প্রযোজ্য হার পণ্য ও লেনদেনের ওপর নির্ভর করতে পারে।", "সব লেনদেনে কি 21% লাগে?", "না। নির্দিষ্ট লেনদেনে 10%, 4% বা 0% হতে পারে। ক্যালকুলেটর শুধু দেওয়া হার প্রয়োগ করে; অব্যাহতি, শূন্য-হার বা সরবরাহের স্থান নির্ধারণ করে না।"],
    irpf: ["ইঞ্জিন বার্ষিক করযোগ্য আয়ের সঙ্গে ব্যবহারকারীর দেওয়া একটি হার গুণ করে: অনুমান=আয়×হার/100; গড় হার=কর/আয়×100। স্পেনের IRPF-এ জাতীয় ও স্বায়ত্তশাসিত অঞ্চলের ধাপ এবং ব্যক্তিগত বিষয় আছে, যা এখানে গণনা হয় না।", "€30,000 বার্ষিক করযোগ্য আয়ে দেওয়া 15% হলে গাণিতিক ফল €4,500, গড় 15%। এটি স্প্যানিশ রিটার্নের কর বা আইনগত হার নয়।", "এটাই কি স্পেনে আমার প্রকৃত IRPF?", "না। আইন 35/2006-এর 63 ও 74 অনুচ্ছেদে জাতীয় ও আঞ্চলিক ধাপ রয়েছে। ছাড়, ব্যক্তিগত/পারিবারিক ন্যূনতম, বসবাসের অঞ্চল ও আয়ের ধরন মডেল করা হয় না।"],
    severance: ["ইঞ্জিন দৈনিক ভিত্তি=মাসিক বেতন×12/365 এবং অনুমান=দৈনিক ভিত্তি×প্রতি চাকরিবর্ষে দেওয়া দিন×চাকরিবর্ষ ব্যবহার করে। স্পেনের শ্রমিক আইন অবসানের কারণভেদে ক্ষতিপূরণ ও সীমা নির্ধারণ করে; টুল কারণ, চুক্তির তারিখ বা আইনি সীমা যাচাই করে না।", "মাসিক €2,500 বেতন, 5 বছর এবং 20 দিন/বছর দিলে দৈনিক ভিত্তি €82.1918, অনুমান €8,219.18। এটি ইনপুট-নির্ভর হিসাব, আইনি অধিকার নির্ধারণ নয়।", "20 বা 33 দিন দিলেই কি আইনি অঙ্ক পাওয়া যায়?", "অবশ্যই নয়। 53 ও 56 অনুচ্ছেদে কারণভেদে হার ও মাসিক সীমা আছে; 12-02-2012-এর আগের চুক্তিতে অন্তর্বর্তী নিয়ম থাকতে পারে। ক্যালকুলেটর এগুলো প্রয়োগ করে না।"],
  },
  uk: {
    vat: ["За введеної ставки r% IVA на суму без податку=сума×r/100, а разом=сума+IVA. Якщо сума вже містить податок, база=разом/(1+r/100). Податкова служба Іспанії, перевірена 28.10.2026, зазначає загальну ставку 21% та 10%, 4% або 0% для окремих операцій; інструмент не класифікує операції.", "Для бази €1 000 за введених 21% IVA становить €210, разом €1 210. Застосовна ставка залежить від товару й операції.", "Чи діє 21% для всіх операцій?", "Ні. Для окремих операцій застосовують 10%, 4% або 0%. Калькулятор лише застосовує введену ставку й не визначає звільнення, нульову ставку чи місце оподаткування."],
    irpf: ["Алгоритм множить річний оподатковуваний дохід на одну введену ставку: оцінка=дохід×ставка/100; середня ставка=податок/дохід×100. Іспанський IRPF має державні й регіональні шкали та особисті фактори, яких інструмент не обчислює.", "За річного доходу €30 000 і введених 15% арифметична оцінка дорівнює €4 500, середня ставка 15%. Це не сума декларації та не законна ставка.", "Це мій фактичний IRPF в Іспанії?", "Ні. Статті 63 і 74 Закону 35/2006 передбачають державні й автономні шкали. Відрахування, особистий/сімейний мінімум, регіон проживання та тип доходу не моделюються."],
    severance: ["Алгоритм використовує денну базу=місячна зарплата×12/365, оцінка=денна база×введені дні за рік стажу×роки стажу. Статут працівників Іспанії встановлює різні суми й межі за підставою припинення; інструмент не визначає підставу, дату договору або законну межу.", "За зарплати €2 500 на місяць, стажу 5 років і введених 20 днів/рік денна база становить €82,1918, оцінка — €8 219,18. Це сценарний розрахунок, а не встановлення права.", "Чи дає введення 20 або 33 днів законну суму?", "Не обов’язково. Статті 53 і 56 встановлюють ставки й місячні обмеження залежно від підстави; для договорів до 12.02.2012 можуть діяти перехідні правила. Калькулятор їх не застосовує."],
  },
  ms: {
    vat: ["Pada kadar input r%, IVA atas nilai bersih=nilai×r/100 dan jumlah=bersih+IVA. Jika amaun sudah termasuk cukai, nilai bersih=jumlah/(1+r/100). Agensi Cukai Sepanyol yang disemak pada 28-10-2026 menyatakan kadar umum 21% serta 10%, 4% atau 0% untuk urus niaga tertentu; alat ini tidak mengelaskan urus niaga.", "Nilai bersih €1,000 pada 21% menghasilkan IVA €210 dan jumlah €1,210. Kadar sebenar mungkin bergantung pada barang dan urus niaga.", "Adakah 21% digunakan untuk semua urus niaga?", "Tidak. Urus niaga tertentu mungkin menggunakan 10%, 4% atau 0%. Kalkulator hanya menggunakan kadar pilihan dan tidak menentukan pengecualian, kadar sifar atau tempat cukai."],
    irpf: ["Enjin mendarab pendapatan bercukai tahunan dengan satu kadar yang dimasukkan: anggaran=pendapatan×kadar/100; kadar purata=cukai/pendapatan×100. IRPF Sepanyol mempunyai skala negara dan wilayah serta faktor peribadi yang tidak dikira oleh alat ini.", "Pendapatan bercukai tahunan €30,000 dengan kadar input 15% memberikan anggaran aritmetik €4,500, purata 15%. Ini bukan amaun penyata cukai atau kadar berkanun.", "Adakah ini cukai IRPF sebenar saya di Sepanyol?", "Tidak. Artikel 63 dan 74 Undang-undang 35/2006 merangkumi skala negara dan wilayah. Potongan, minimum peribadi/keluarga, wilayah kediaman dan jenis pendapatan tidak dimodelkan."],
    severance: ["Enjin menggunakan asas harian=gaji bulanan×12/365 dan anggaran=asas harian×hari bagi setiap tahun perkhidmatan yang dimasukkan×tahun perkhidmatan. Statut Pekerja Sepanyol menetapkan pampasan dan had berbeza mengikut sebab penamatan; alat tidak menentukan sebab, tarikh kontrak atau had undang-undang.", "Gaji bulanan €2,500, tempoh 5 tahun dan input 20 hari/tahun menghasilkan asas harian €82.1918 dan anggaran €8,219.18. Ini kiraan andaian, bukan penentuan hak undang-undang.", "Adakah input 20 atau 33 hari memberikan amaun undang-undang?", "Tidak semestinya. Artikel 53 dan 56 menetapkan kadar serta had bulanan mengikut sebab; kontrak sebelum 12-02-2012 mungkin tertakluk pada peraturan peralihan. Kalkulator tidak menerapkannya."],
  },
  sv: {
    vat: ["Med inmatad skattesats r % är IVA på belopp exklusive skatt=belopp×r/100 och total=netto+IVA. För ett belopp inklusive skatt är netto=total/(1+r/100). Spaniens skattemyndighet, kontrollerad 2026-10-28, anger 21 % som allmän skattesats och 10 %, 4 % eller 0 % för vissa transaktioner; verktyget klassificerar inte transaktioner.", "1 000 € netto med inmatade 21 % ger 210 € IVA och 1 210 € totalt. Rätt skattesats kan bero på vara och transaktion.", "Gäller 21 % för varje transaktion?", "Nej. Vissa transaktioner har 10 %, 4 % eller 0 %. Kalkylatorn använder bara den valda satsen och avgör inte undantag, nollskatt eller beskattningsort."],
    irpf: ["Motorn multiplicerar årsinkomsten som angetts som beskattningsbar med en enda vald skattesats: uppskattning=inkomst×sats/100; genomsnittlig sats=skatt/inkomst×100. Spansk IRPF har statliga och regionala skikt samt personliga faktorer som verktyget inte beräknar.", "Vid 30 000 € årsinkomst och inmatade 15 % blir den aritmetiska uppskattningen 4 500 €, i genomsnitt 15 %. Det är inte deklarerad skatt eller lagstadgad sats.", "Är detta min faktiska IRPF i Spanien?", "Nej. Artiklarna 63 och 74 i lag 35/2006 omfattar statliga och regionala skatteskalor. Avdrag, personligt/familjeminimum, region och inkomstslag modelleras inte."],
    severance: ["Motorn använder dagsunderlag=månadslön×12/365 och uppskattning=dagsunderlag×inmatade dagar per tjänsteår×tjänsteår. Spaniens arbetstagarstadga har olika ersättning och tak beroende på avslutsgrund; verktyget fastställer inte grund, avtalsdatum eller lagstadgat tak.", "Med 2 500 € i månadslön, 5 år och inmatade 20 dagar/år blir dagsunderlaget 82,1918 € och uppskattningen 8 219,18 €. Det är ett antagandebaserat räkneexempel, inte ett juridiskt beslut.", "Ger 20 eller 33 dagar det lagliga beloppet?", "Inte nödvändigtvis. Artiklarna 53 och 56 anger procentsatser och månadstak efter grund; avtal före 2012-02-12 kan omfattas av övergångsregler. Kalkylatorn tillämpar inte reglerna."],
  },
  cs: {
    vat: ["Při zadané sazbě r % je IVA z částky bez daně=částka×r/100 a celkem=netto+IVA. U částky včetně daně je základ=celkem/(1+r/100). Španělská daňová správa ověřená 28. 10. 2026 uvádí obecnou sazbu 21 % a 10 %, 4 % či 0 % pro vybraná plnění; nástroj plnění netřídí.", "Základ 1 000 € při zadaných 21 % znamená IVA 210 € a celkem 1 210 €. Použitelná sazba závisí na zboží a transakci.", "Platí 21 % pro všechny transakce?", "Ne. Pro některá plnění platí 10 %, 4 % nebo 0 %. Kalkulačka použije jen zadanou sazbu a neurčí osvobození, nulovou sazbu ani místo zdanění."],
    irpf: ["Výpočet násobí zadaný roční zdanitelný příjem jedinou zadanou sazbou: odhad=příjem×sazba/100; průměrná sazba=daň/příjem×100. Španělská IRPF zahrnuje státní a autonomní stupnice a osobní okolnosti, které nástroj nepočítá.", "Při ročním zdanitelném příjmu 30 000 € a zadaných 15 % vyjde aritmetický odhad 4 500 €, průměrně 15 %. Nejde o daň v přiznání ani zákonnou sazbu.", "Je to moje skutečná daň IRPF ve Španělsku?", "Ne. Články 63 a 74 zákona 35/2006 upravují státní a regionální stupnice; odpočty, osobní/rodinné minimum, autonomní oblast a druh příjmu zde nejsou modelovány."],
    severance: ["Výpočet používá denní základ=měsíční mzda×12/365 a odhad=denní základ×zadané dny za rok služby×roky služby. Španělský statut pracovníků stanoví různá plnění a stropy podle důvodu ukončení; nástroj důvod, datum smlouvy ani zákonný strop neověřuje.", "Při 2 500 € měsíčně, 5 letech a zadaných 20 dnech/rok činí denní základ 82,1918 € a odhad 8 219,18 €. Jde o výpočet podle předpokladu, nikoli potvrzení právního nároku.", "Dá zadání 20 nebo 33 dnů zákonnou částku?", "Ne nutně. Články 53 a 56 stanoví sazby a měsíční stropy podle důvodu; smlouvy před 12. 2. 2012 mohou podléhat přechodným pravidlům. Kalkulačka je neuplatňuje."],
  },
  ro: {
    vat: ["La rata introdusă r% dă TVA la suma netă=suma×r/100 și total=net+TVA. Pentru un total cu TVA inclus, net=total/(1+r/100). Agenția fiscală spaniolă, verificată la 28.10.2026, indică 21% ca rată generală și 10%, 4% sau 0% pentru anumite operațiuni; instrumentul nu clasifică operațiunile.", "La o bază netă de 1.000 € și 21% introduse, TVA este 210 €, totalul 1.210 €. Rata aplicabilă poate depinde de bun și tranzacție.", "Se aplică 21% tuturor tranzacțiilor?", "Nu. Unele operațiuni folosesc 10%, 4% sau 0%. Calculatorul aplică doar rata introdusă și nu stabilește scutirea, rata zero sau locul taxării."],
    irpf: ["Motorul înmulțește venitul anual impozabil introdus cu o singură rată: estimare=venit×rată/100; rată medie=impozit/venit×100. IRPF spaniol are grile naționale și regionale și factori personali pe care acest instrument nu îi calculează.", "La un venit impozabil anual de 30.000 € și o rată introdusă de 15%, estimarea aritmetică este 4.500 €, media 15%. Nu este suma declarației sau o cotă legală.", "Este impozitul IRPF datorat efectiv în Spania?", "Nu. Articolele 63 și 74 din Legea 35/2006 prevăd grile naționale și regionale. Deducerile, minimul personal/familial, regiunea și tipul venitului nu sunt modelate."],
    severance: ["Motorul folosește baza zilnică=salariu lunar×12/365 și estimarea=baza zilnică×zile introduse pe an de vechime×ani de vechime. Statutul lucrătorilor din Spania stabilește indemnizații și limite diferite după motivul încetării; instrumentul nu verifică motivul, data contractului sau plafonul legal.", "La 2.500 € lunar, 5 ani și 20 zile/an introduse, baza zilnică este 82,1918 €, iar estimarea 8.219,18 €. Este un scenariu de calcul, nu constatarea unui drept legal.", "Introducerea a 20 sau 33 de zile oferă suma legală?", "Nu neapărat. Articolele 53 și 56 stabilesc rate și limite lunare în funcție de motiv; contractele anterioare datei de 12.02.2012 pot avea reguli tranzitorii. Calculatorul nu le aplică."],
  },
  el: {
    vat: ["Με συντελεστή r% που εισάγετε, ΦΠΑ σε καθαρή αξία=ποσό×r/100 και σύνολο=καθαρή αξία+ΦΠΑ. Για ποσό με ΦΠΑ, καθαρή αξία=σύνολο/(1+r/100). Η ισπανική φορολογική υπηρεσία, με έλεγχο στις 28-10-2026, αναφέρει γενικό συντελεστή 21% και 10%, 4% ή 0% για συγκεκριμένες πράξεις· το εργαλείο δεν τις ταξινομεί.", "Καθαρή αξία €1.000 με εισαγόμενο 21% δίνει ΦΠΑ €210 και σύνολο €1.210. Ο εφαρμοστέος συντελεστής μπορεί να εξαρτάται από το αγαθό και τη συναλλαγή.", "Ισχύει το 21% για κάθε συναλλαγή;", "Όχι. Ορισμένες πράξεις έχουν 10%, 4% ή 0%. Η αριθμομηχανή εφαρμόζει μόνο τον επιλεγμένο συντελεστή και δεν κρίνει απαλλαγές, μηδενικό συντελεστή ή τόπο φορολόγησης."],
    irpf: ["Ο μηχανισμός πολλαπλασιάζει το ετήσιο φορολογητέο εισόδημα με έναν συντελεστή που εισάγει ο χρήστης: εκτίμηση=εισόδημα×συντελεστής/100· μέσος συντελεστής=φόρος/εισόδημα×100. Οι κρατικές και περιφερειακές κλίμακες και οι προσωπικοί παράγοντες του ισπανικού IRPF δεν υπολογίζονται εδώ.", "Για ετήσιο φορολογητέο εισόδημα €30.000 και εισαγόμενο 15%, η αριθμητική εκτίμηση είναι €4.500, μέσος 15%. Δεν είναι ποσό δήλωσης ή νόμιμος συντελεστής.", "Είναι αυτός ο πραγματικός φόρος IRPF στην Ισπανία;", "Όχι. Τα άρθρα 63 και 74 του νόμου 35/2006 καλύπτουν κρατικές και περιφερειακές κλίμακες. Εκπτώσεις, προσωπικό/οικογενειακό αφορολόγητο, περιφέρεια και είδος εισοδήματος δεν μοντελοποιούνται."],
    severance: ["Ο μηχανισμός χρησιμοποιεί ημερήσια βάση=μηνιαίος μισθός×12/365 και εκτίμηση=ημερήσια βάση×ημέρες ανά έτος υπηρεσίας που εισάγετε×έτη υπηρεσίας. Το ισπανικό Καταστατικό Εργαζομένων προβλέπει διαφορετικά ποσά και όρια ανά λόγο λύσης· το εργαλείο δεν ελέγχει λόγο, ημερομηνία σύμβασης ή νόμιμο όριο.", "Με €2.500 τον μήνα, 5 έτη και εισαγόμενες 20 ημέρες/έτος, η ημερήσια βάση είναι €82,1918 και η εκτίμηση €8.219,18. Είναι υποθετικός υπολογισμός, όχι αναγνώριση δικαιώματος.", "Δίνουν οι 20 ή 33 ημέρες το νόμιμο ποσό;", "Όχι απαραίτητα. Τα άρθρα 53 και 56 καθορίζουν ποσοστά και μηνιαία όρια ανά λόγο· συμβάσεις πριν από 12-02-2012 μπορεί να έχουν μεταβατικούς κανόνες. Ο υπολογιστής δεν τους εφαρμόζει."],
  },
};

